Translate("ptBR", "un-goro-crater", {
	title = "Cratera Un'Goro",
	aliases = { "Un'Goro", "a Cratera" },
	sections = {
		{
			title = "Resumo",
			text = [=[A Cratera Un'Goro é uma vasta bacia verde afundada no sul de {link:kalimdor}Kalimdor{/link}, cercada por penhascos entre as areias de {link:tanaris}Tanaris{/link} e os ermos arruinados de {link:silithus}Silithus{/link}. Abaixo de sua borda, o mundo parece pertencer a outra era. O vapor sobe de suas fontes, um vulcão fumega em seu coração, e a selva é governada por feras que o resto do mundo esqueceu há muito tempo: demossauros estrondosos, estegodontes, pterrordax alados e bandos de ravassauros. Cristais estranhos cintilam na relva, e altos {link:crystal-pylons}pilones de cristal{/link} se erguem na orla da mata.]=],
		},
		{
			title = "Origens",
			text = [=[Nenhuma crônica registra como a cratera se formou, nem quando. As histórias da era mais antiga afirmam que os servos dos {red:titans}Titãs{/red} moldaram certas terras do mundo jovem como jardins de vida selvagem, e que Un'Goro estava entre elas. Os {link:crystal-pylons}pilones de cristal{/link} ao redor de sua borda são mais antigos que qualquer povo que hoje vive em {link:kalimdor}Kalimdor{/link}, e ninguém que habita a cratera sabe dizer quem os ergueu nem por quê. Os {link:tauren}taurens{/link} que vêm caçar aqui sentem com força a presença da Mãe Terra na bacia. Para eles, suas criaturas são parentes mais nobres das feras de suas próprias planícies.]=],
		},
		{
			title = "O Presente",
			text = [=[A cratera atraiu nos últimos tempos uma multidão de curiosos e de perdidos. Uma trupe de exploradores liderada por {link:williden-marshal}Williden Marshal{/link} veio estudar a terra e quase foi destruída por ela. Seus sobreviventes ocupam um refúgio rochoso nas alturas do norte, onde goblins de {link:gadgetzan}Geringontzan{/link}, estudiosos errantes e viajantes perdidos se reuniram em volta deles. O {link:cenarion-circle}Círculo Cenariano{/link} mandou buscar o solo da cratera, que dizem conter magia poderosa, e druidas em {link:darnassus}Darnassus{/link} e no {link:thunder-bluff}Penhasco do Trovão{/link} o estudam. No sul, os insetos da colmeia Gorishi cavaram a terra. Sua presença inquieta os estudiosos, pois nada como eles pertence à ordem natural da cratera. Nestes dias, os mapas também nomeiam o {red:shaper-s-terrace}Shaper's Terrace{/red} dentro da cratera, um lugar cuja história é contada em sua própria página.]=],
		},
		{
			title = "Habitantes",
			text = [=[• {b}Os grandes sáurios.{/b} Demossauros caçam por toda a bacia. Estegodontes pastam no sudoeste, ravassauros correm em bandos no sudeste, e diemetradons se aquecem ao longo de seus caminhos.
• {b}Os macacos da {link:fungal-rock}Pedra do Limo{/link}.{/b} Grandes gorilas ocupam as cavernas do nordeste e expulsam quem se aproxima.
• {b}Os Gorishi.{/b} Uma colmeia de insetos escavou a {link:the-slithering-scar}Fenda Coleante{/link}, no sul.
• {b}Elementais.{/b} Seres de chama viva andam pelas encostas do vulcão, e criaturas de piche se erguem dos poços do norte.
• {b}Pétalas-de-sangue e gosmas.{/b} Plantas carnívoras rastejam pelas moitas do leste, e lodos se juntam nos pântanos.
• {b}Os recém-chegados.{/b} Exploradores, engenhoqueiros de {link:gadgetzan}Geringontzan{/link} e errantes perdidos lotam o {link:marshal-s-refuge}Refúgio do Marshal{/link}, e um caçador {link:tauren}tauren{/link} mantém seu próprio acampamento onde a estrada de {link:tanaris}Tanaris{/link} entra na cratera.]=],
		},
		{
			title = "História",
			text = [=[• {b}A Era dos Criadores.{/b} Os pilones e cristais da cratera restam de um tempo anterior a qualquer reino mortal. Nenhuma história mortal registra sua construção.
• {b}A Expedição Marshal.{/b} A trupe de {link:williden-marshal}Williden Marshal{/link} montou acampamentos no sudoeste e no nordeste da cratera. As feras tomaram ambos, e os sobreviventes fugiram para o norte, para terreno mais alto.
• {b}O Presente.{/b} Estudiosos, druidas, caçadores e pelo menos um errante que não se lembra por que veio procuram agora a cratera.]=],
		},
		{
			title = "Lendas da Cratera",
			text = [=[• No {link:marshal-s-refuge}Refúgio do Marshal{/link}, diz-se que os pilones e os cristais coloridos na relva estão ligados, e que a mistura certa de cores despertará seu poder.
• {link:krakle}Krakle{/link}, de {link:gadgetzan}Geringontzan{/link}, acredita que as fontes de {link:golakka-hot-springs}Golakka{/link} tiram seu calor do vulcão, embora suas contas ainda não estejam terminadas.
• {link:torwa-pathfinder}Torwa Pathfinder{/link} avisa que {link:lar-korwi}Lar'korwi{/link}, o grande ravassauro do leste, perseguirá por dias quem roubar de sua caça.]=],
		},
	},
})

Translate("ptBR", "marshal-s-refuge", {
	title = "Refúgio do Marshal",
	sections = {
		{
			title = "Resumo",
			text = [=[{link:the-harborage}O Refúgio{/link} do Marshal é um acampamento de tendas e fogueiras de cozinha instalado entre as rochas da parede norte da cratera. Foi fundado em fuga. Quando as feras de {link:un-goro-crater}Un'Goro{/link} tomaram os acampamentos das Expedições Marshal, {link:williden-marshal}Williden Marshal{/link} e sua gente subiram a este terreno alto, onde os grandes sáurios não podiam segui-los com facilidade. Outros se juntaram a eles desde então: um mestre de voo de {link:gadgetzan}Geringontzan{/link}, errantes perdidos, viajantes que brigam entre si e uma estudiosa de cristais que trabalha na caverna acima do acampamento. O refúgio é o único lugar da cratera onde um viajante pode dormir sem manter um olho aberto.]=],
		},
	},
})

Translate("ptBR", "fire-plume-ridge", {
	title = "Pico Penacho de Fogo",
	sections = {
		{
			title = "Resumo",
			text = [=[O Pico Penacho de Fogo é o vulcão no centro de {link:un-goro-crater}Un'Goro{/link}, um cone carbonizado que derrama fumaça e calor sobre toda a cratera. Suas encostas pertencem a elementais de chama viva. Em seu coração, em caminhos de rocha enegrecida, habita {link:blazerunner}Blazerunner{/link}, um elemental envolto numa aura que nenhuma lâmina jamais atravessou. Ele guarda uma caverna que abriga a Chama Dourada. O calor do pico é forte o bastante para vencer os desavisados, e o explorador {link:ringo}Ringo{/link} quase morreu por causa dele. Os que estudam a cratera acreditam que o vulcão pode aquecer suas fontes.]=],
		},
	},
})

Translate("ptBR", "golakka-hot-springs", {
	title = "Fontes Termais Golakka",
	aliases = { "Golakka" },
	sections = {
		{
			title = "Resumo",
			text = [=[As Fontes Termais Golakka fumegam na parte oeste da cratera, uma cadeia de poças quentes em meio à selva. {link:krakle}Krakle{/link}, um estudioso de {link:gadgetzan}Geringontzan{/link}, montou seu acampamento ao lado delas, longe da segurança do refúgio. Ele quer saber de onde vem o calor delas, e desconfia do vulcão do {link:fire-plume-ridge}Pico Penacho de Fogo{/link}, não muito longe a leste. Suas medições o levaram a se perguntar sobre outras fontes na distante {link:winterspring}Hibérnia{/link}, onde não há vulcão algum.]=],
		},
	},
})

Translate("ptBR", "lakkari-tar-pits", {
	title = "Poços de Piche Lakkari",
	aliases = { "Lakkari" },
	sections = {
		{
			title = "Resumo",
			text = [=[Os Poços de Piche Lakkari ficam no norte da cratera, ao sul do {link:marshal-s-refuge}Refúgio do Marshal{/link}. Piche negro borbulha do chão aqui em poças largas e grudentas. Dele se erguem criaturas de piche que parecem viver e se mover por vontade própria. As maiores delas, os senhores do piche, espreitam perto das poças do norte. Feras e rastejadores de piche menores vagam mais ao sul, em direção às planícies abaixo do vulcão. Nenhum registro diz quem deu nome aos poços.]=],
		},
	},
})

Translate("ptBR", "the-slithering-scar", {
	title = "Fenda Coleante",
	sections = {
		{
			title = "Resumo",
			text = [=[{link:the-cleft}A Fenda{/link} Coleante é um grande rasgo no chão sul da cratera, onde os insetos Gorishi construíram sua colmeia. Vespas enchem o ar acima dela, e operárias, saqueadores e escavadores rastejam por suas passagens. Em câmaras profundas cobertas de crias larvais, a colmeia gera seus filhotes, e uma rainha os governa lá de dentro. {link:hol-anyee-marshal}Hol'anyee Marshal{/link} estudava os Gorishi quando sua expedição fugiu. A seus olhos, eles não pertencem de forma alguma à cratera.]=],
		},
	},
})

Translate("ptBR", "terror-run", {
	title = "Terroral",
	sections = {
		{
			title = "Resumo",
			text = [=[Terroral é a planície do sudoeste da cratera, e fez por merecer seu nome. Estegodontes pastam por ela em rebanhos pesados, e demossauros caçam entre eles. As Expedições Marshal vieram aqui escavar os ossos de feras mortas. Os escavadores logo descobriram que as vivas eram muito mais numerosas, e muito mais perigosas. {link:spark-nilminer}Spark Nilminer{/link}, o escavador-chefe da expedição, ainda fala do lugar com pavor declarado. Ele o chama de armadilha mortal, e não diz isso por brincadeira.]=],
		},
	},
})

Translate("ptBR", "fungal-rock", {
	title = "Pedra do Limo",
	sections = {
		{
			title = "Resumo",
			text = [=[A Pedra do Limo é um oco de cavernas no nordeste da cratera, e é o covil dos grandes macacos de {link:un-goro-crater}Un'Goro{/link}. Gorilas, pisoteadores e trovejadores o defendem, e nenhum é mais feroz que o macaco poderoso que o caçador {link:tauren}tauren{/link} {link:torwa-pathfinder}Torwa{/link} chama de {link:u-cha}U'cha{/link}. A inventora {link:karna-remtravel}Karna Remtravel{/link} mandou sua macaca mecânica, {link:a-me-01}A-Me 01{/link}, a essas cavernas para observar os macacos de perto. Os macacos não se deixaram enganar por muito tempo. Quando viajantes a encontraram de novo, ela jazia silenciosa e muito amassada na boca das cavernas.]=],
		},
	},
})

Translate("ptBR", "the-marshlands", {
	title = "Os Pântanos",
	aliases = { "Pântanos" },
	sections = {
		{
			title = "Resumo",
			text = [=[Os Pântanos são as terras baixas e úmidas do leste da cratera, uma região de lama, juncos e água parada. Lodos de muitos tipos se juntam em suas poças, e pétalas-de-sangue rastejam por suas moitas. Um dos acampamentos abandonados da expedição ficava deste lado da cratera, e seus mantimentos ficaram intocados na lama muito depois de os exploradores fugirem. Uma jangada destroçada repousa ao lado de um pequeno lago mais ao sul, longe de qualquer água que pudesse tê-la levado até ali. Pertencia ao errante {link:linken}Linken{/link}, embora ele já não se lembrasse disso.]=],
		},
	},
})

Translate("ptBR", "crystal-pylons", {
	title = "Pilones de Cristal",
	aliases = { "pilones de cristal", "os pilones de Un'Goro" },
	sections = {
		{
			title = "Resumo",
			text = [=[Três pilones de cristal se erguem nas matas da {link:un-goro-crater}Cratera Un'Goro{/link}: um no norte, um junto à parede leste e um no oeste. São altas obras de pedra revestidas por dentro de cristal, e são muito mais antigas que o acampamento de qualquer explorador vivo. Por muito tempo, foram apenas boatos contados no {link:marshal-s-refuge}Refúgio do Marshal{/link}.]=],
		},
		{
			title = "Os Cristais",
			text = [=[Cristais coloridos jazem espalhados pelo chão da cratera: vermelhos, azuis, amarelos e verdes. A maioria dos viajantes os ignora. A gnomida {link:j-d-collie}J.D. Collie{/link} não. Ela os recolheu aos sacos e tentou todas as combinações que conseguiu imaginar, mas eles nada revelaram até que os pilones fossem encontrados. Depois que viajantes examinaram os três, ela estudou o que eles tinham visto e escreveu suas descobertas num manual. Com ele, os cristais podiam ser fundidos em combinações que restauram, fortalecem, protegem e energizam quem os carrega.]=],
		},
		{
			title = "Sem Resposta",
			text = [=[Quem ergueu os pilones, e com que fim, a cratera não diz. {link:j-d-collie}J.D. Collie{/link} aprendeu a usar seus cristais. Não aprendeu por que eles estavam ali.]=],
		},
	},
})

Translate("ptBR", "williden-marshal", {
	title = "Williden Marshal",
	subtitle = "Líder das Expedições Marshal",
	found = "Refúgio do Marshal, entre as tendas",
	hint = [=[Fale com o líder da expedição que se refugiou nas alturas do norte da cratera.]=],
	allegiance = "Expedições Marshal",
	aliases = { "Williden" },
	sections = {
		{
			title = "Resumo",
			text = [=[Williden Marshal lidera as Expedições Marshal, uma trupe de exploradores que não responde a nação alguma. Ele os trouxe à {link:un-goro-crater}Cratera Un'Goro{/link} para estudá-la, e a cratera quase matou todos eles. Agora ele mantém vivo o que resta de sua gente nas alturas rochosas que levam seu nome.]=],
		},
		{
			title = "Importância",
			text = [=[Williden é a razão de haver algum terreno seguro na cratera. O refúgio que sua gente construiu na fuga tornou-se o ponto de encontro de todos que vêm a {link:un-goro-crater}Un'Goro{/link}, seja por escolha, seja por infortúnio. Ele não finge que a expedição correu bem. Admite que sua trupe subestimou demais a selvageria da cratera.]=],
		},
		{
			title = "Feitos",
			text = [=[• Liderou a expedição que montou acampamentos no sudoeste e no nordeste da cratera.
• Quando as feras tomaram os dois acampamentos, conduziu os sobreviventes ao norte, para terreno mais alto.
• Pede a viajantes que recuperem a comida e o equipamento de pesquisa que sua gente deixou para trás.
• Mantém um diário da expedição, que se perdeu na fuga.]=],
		},
		{
			title = "Não Registrado",
			text = [=[Nenhum registro diz de onde Williden veio nem como fundou sua trupe. Esta entrada registra apenas o que a cratera fez dele.]=],
		},
	},
	chapters = {
		{
			title = "A Salvação da Expedição",
			hint = "Recupere o que a expedição abandonou em sua fuga.",
			text = [=[Os acampamentos foram deixados às pressas, e com eles ficaram tanto a comida da expedição quanto seus instrumentos. Sem uma, os exploradores passariam fome. Sem os outros, todo o seu sofrimento teria sido em vão. Quando ambos foram levados de volta ao refúgio, Williden declarou que a própria expedição tinha sido salva, e passou a contar quem a salvou como amigo de sua companhia pelo resto da vida.]=],
		},
		{
			title = "O Diário Estraçalhado",
			hint = "Devolva um diário perdido ao seu dono.",
			text = [=[Um diário rasgado e pisoteado foi encontrado na mata. Ainda se podia ler o bastante para contar a história da expedição: os acampamentos tomados, a fuga, a busca por terreno alto no norte. Williden o contava entre as muitas coisas que a cratera lhe tirara. Ficou feliz em tê-lo de volta.]=],
		},
	},
	mentions = {
		{ text = "A Salvação da Expedição" },
		{ text = "O Diário de Williden" },
	},
	bonds = {
		{ id = "hol-anyee-marshal", name = "Hol'anyee Marshal", note = "compartilha seu nome e sua expedição" },
		{ id = "spark-nilminer", name = "Spark Nilminer", note = "seu escavador-chefe" },
	},
})

Translate("ptBR", "hol-anyee-marshal", {
	title = "Hol'anyee Marshal",
	subtitle = "Estudiosa das Expedições Marshal",
	found = "Refúgio do Marshal, ao lado de Williden",
	hint = [=[Fale com a estudiosa da expedição, que fica ao lado de seu líder.]=],
	allegiance = "Expedições Marshal",
	aliases = { "Hol'anyee" },
	sections = {
		{
			title = "Resumo",
			text = [=[Hol'anyee Marshal é uma estudiosa das Expedições Marshal. Antes que a expedição fugisse para o norte, ela estudava os insetos Gorishi do sul da cratera. A retirada não pôs fim ao seu trabalho. Ela acredita que os Gorishi são estranhos à vida da cratera, e pretende descobrir como chegaram ali.]=],
		},
		{
			title = "Importância",
			text = [=[Hol'anyee é a primeira a dizer em voz alta que a colmeia Gorishi não pertence a {link:un-goro-crater}Un'Goro{/link}.]=],
		},
		{
			title = "Feitos",
			text = [=[• Estudou os Gorishi no sul antes que os acampamentos fossem tomados.
• Mandou um frasco raspador à colmeia para tirar uma amostra das paredes de seus criadouros.]=],
		},
	},
	mentions = {
		{ text = "Ecologia Alienígena" },
	},
	bonds = {
		{ id = "williden-marshal", name = "Williden Marshal", note = "lidera a expedição" },
	},
})

Translate("ptBR", "spark-nilminer", {
	title = "Spark Nilminer",
	subtitle = "Escavador-chefe das Expedições Marshal",
	found = "Refúgio do Marshal",
	hint = [=[Encontre o escavador da expedição, que já perdeu o gosto por escavar.]=],
	allegiance = "Expedições Marshal",
	aliases = { "Spark" },
	sections = {
		{
			title = "Resumo",
			text = [=[Spark Nilminer é o escavador-chefe das Expedições Marshal. Sua tarefa era desenterrar os ossos de estegodontes e diemetradons mortos em {link:terror-run}Terroral{/link}. As feras vivas tornaram esse trabalho quase impossível, e Spark passou a odiar o lugar. {link:williden-marshal}Williden{/link} e {link:hol-anyee-marshal}Hol'anyee{/link} ainda querem seus ossos, e Spark prefere não perguntar como são recolhidos.]=],
		},
		{
			title = "Importância",
			text = [=[Spark fala pelos membros comuns da expedição, que vieram trabalhar e agora só querem sair vivos.]=],
		},
		{
			title = "Feitos",
			text = [=[• Foi mandado escavar ossos em {link:terror-run}Terroral{/link}.
• Aceita ossos de qualquer origem, e pede aos viajantes que não digam de onde vieram.]=],
		},
	},
	mentions = {
		{ text = "Rolem os Ossos" },
	},
	bonds = {
		{ id = "williden-marshal", name = "Williden Marshal", note = "seu líder" },
	},
})

Translate("ptBR", "j-d-collie", {
	title = "J.D. Collie",
	subtitle = "Estudiosa dos Cristais",
	found = "A caverna acima do Refúgio do Marshal",
	hint = [=[Procure a gnomida que trabalha com cristais luminosos na caverna acima do refúgio.]=],
	allegiance = "Refúgio do Marshal",
	aliases = { "J.D." },
	sections = {
		{
			title = "Resumo",
			text = [=[J.D. Collie é uma gnomida que montou sua oficina na caverna acima do {link:marshal-s-refuge}Refúgio do Marshal{/link}. Ela é fascinada pelos cristais coloridos que jazem por toda {link:un-goro-crater}Un'Goro{/link} e pelos boatos de grandes pilones na mata. Acredita em quase toda história que ouve, e na cratera essa confiança a serviu surpreendentemente bem.]=],
		},
		{
			title = "Importância",
			text = [=[J.D. é a primeira a entender os {link:crystal-pylons}pilones de cristal{/link}. Outros passaram pelos cristais durante anos. Ela os recolheu, testou e por fim aprendeu a unir seu poder. Foi também gentil com o errante {link:linken}Linken{/link} quando ele chegou cambaleando ao refúgio pela primeira vez, e as poucas palavras que ele lhe disse em sua confusão foram a chave de sua memória.]=],
		},
		{
			title = "Feitos",
			text = [=[• Recolhe cristais de quatro cores e os testa em combinações sem fim.
• Manda viajantes encontrar os pilones do norte, do leste e do oeste.
• Escreveu um manual dos pilones e dos cristais.
• Apontou a busca pelo passado de {link:linken}Linken{/link} para {link:eridan-bluewind}Eridan Bluewind{/link}, na {link:felwood}Selva Maleva{/link}.]=],
		},
	},
	chapters = {
		{
			title = "Os Três Pilones",
			hint = "Encontre os pilones de cristal de que J.D. ouviu falar.",
			text = [=[Por muito tempo, os experimentos de J.D. não deram em nada, e ela começou a temer que os cristais não tivessem poder algum. Então viajantes encontraram os pilones um a um: um no norte, um junto à parede leste, um no oeste. Ela pegou o que eles tinham visto e estudou tudo em sua caverna. Quando terminou, sabia como os cristais podiam ser unidos, e registrou tudo num livro.]=],
		},
		{
			title = "A Memória de uma Gnomida",
			hint = [=[Pergunte à gnomida dos cristais o que o errante perdido lhe disse certa vez.]=],
			text = [=[Quando {link:linken}Linken{/link} chegou ao refúgio, estava atordoado e cheio de resmungos estranhos. J.D. lembrava uma coisa que ele dissera: que estava fazendo um totem, e que precisava encontrar alguém chamado {link:eridan-bluewind}Eridan Bluewind{/link} na {link:felwood}Selva Maleva{/link}. Era um fio pequeno, mas levou até {link:blazerunner}Blazerunner{/link}.]=],
		},
	},
	mentions = {
		{ text = "Cristais de Poder" },
		{ text = "O Pilone do Norte" },
		{ text = "O Pilone do Leste" },
		{ text = "O Pilone do Oeste" },
		{ text = "Entendendo Tudo" },
		{
			text = [=[A Ajuda de uma Gnomida, enviada por {link:linken}Linken{/link}]=],
		},
		{ text = "A Memória de {link:linken}Linken{/link}" },
		{ text = "Aquementas, o totem trazido a ela" },
		{ text = "A Aventura de {link:linken}Linken{/link}" },
	},
	bonds = {
		{ id = "linken", name = "Linken", note = "lembrou o que ele esqueceu" },
		{ id = "eridan-bluewind", name = "Eridan Bluewind", note = "o nome que Linken pronunciou" },
	},
})

Translate("ptBR", "linken", {
	title = "Linken",
	subtitle = "O Errante sem Memória",
	found = "Refúgio do Marshal",
	hint = [=[Fale com o errante do refúgio que não se lembra de como chegou ali.]=],
	allegiance = "Nenhuma de que se lembre",
	sections = {
		{
			title = "Resumo",
			text = [=[Linken é um {link:gnomes}gnomo{/link} que chegou à {link:un-goro-crater}Cratera Un'Goro{/link} sem memória de quem era nem de por que viera. Sabe apenas que algo importante o trouxe aqui. Ao contrário da maioria de seu povo, não tem interesse em engenhocas. {link:j-d-collie}J.D. Collie{/link} desconfia que ele seja um guerreiro de coração.]=],
		},
		{
			title = "Importância",
			text = [=[A missão esquecida de Linken revela-se um dos grandes feitos da cratera. Ele veio enfrentar {link:blazerunner}Blazerunner{/link}, o elemental envolto em chamas do {link:fire-plume-ridge}Pico Penacho de Fogo{/link}, e tomar dele um artefato de poder terrível. Quando sua memória volta, ele não reivindica o feito para si. Entrega-o a quem o restaurou.]=],
		},
		{
			title = "Feitos",
			text = [=[• Veio a {link:un-goro-crater}Un'Goro{/link} numa longa jornada cujo último passo foi a derrota de {link:blazerunner}Blazerunner{/link}.
• Buscou com {link:eridan-bluewind}Eridan Bluewind{/link}, da {link:felwood}Selva Maleva{/link}, um totem forte o bastante para arrancar a aura de Blazerunner.
• Pretende levar a Chama Dourada de volta à sua terra natal, onde nunca mais poderá ser usada para o mal.]=],
		},
		{
			title = "Não Registrado",
			text = [=[A terra natal de Linken não é nomeada, e ele não disse quem era antes de perder a memória.]=],
		},
	},
	chapters = {
		{
			title = "A Mochila Perdida",
			hint = "Devolva uma mochila perdida ao seu dono no refúgio.",
			text = [=[Uma jangada destroçada jazia ao lado de um pequeno lago, longe de qualquer água que pudesse tê-la levado. No fundo do lago havia uma mochila encharcada: uma bússola, um mapa enrolado e uma chave em forma de cabeça de leão. Linken olhou para eles e algo se agitou. Lembrou-se de uma espada que precisava fortalecer, embora não soubesse por quê. Mandou-a ao norte, para {link:donova-snowden}Donova Snowden{/link}, em {link:winterspring}Hibérnia{/link}.]=],
		},
		{
			title = "A Espada Temperada",
			hint = "Veja a espada de Linken terminada.",
			text = [=[A espada passou de mão em mão. {link:donova-snowden}Donova{/link} a temperou em suas fontes termais. Um elixir de {link:gregan-brewspewer}Gregan Brewspewer{/link}, de {link:feralas}Feralas{/link}, permitiu a seu portador andar como espírito perto de {link:gadgetzan}Geringontzan{/link} e falar com o fantasma {red:gaeriyan}Gaeriyan{/red}. Sob uma lápide ali, a espada foi transformada num clarão de luz. Linken a segurou de novo e ainda não soube dizer para que servia.]=],
		},
		{
			title = "A Chama Dourada",
			hint = "Termine o que Linken veio fazer na cratera.",
			text = [=[O totem de Aquementas enfim lhe devolveu a memória. Linken soube então que viera lutar contra {link:blazerunner}Blazerunner{/link}, que guardava a Chama Dourada. Soube também que já não era ele quem deveria fazê-lo. Quando Blazerunner caiu e a Chama lhe foi trazida, ele prometeu levá-la para casa e mantê-la em segurança.]=],
		},
	},
	mentions = {
		{ text = "É um Segredo para Todos" },
		{ text = "É um Segredo para Todos, a mochila perdida" },
		{ text = "É um Segredo para Todos, a espada" },
		{ text = "O Elixir Videre" },
		{ text = "Encontro no Túmulo" },
		{ text = "Uma Situação Grave" },
		{ text = "A Espada de Linken" },
		{ text = "A Ajuda de uma Gnomida" },
		{ text = "Coração de Prata" },
		{ text = "Aquementas" },
		{ text = "A Aventura de Linken" },
		{ text = "É Perigoso Ir Sozinho" },
	},
	bonds = {
		{ id = "j-d-collie", name = "J.D. Collie", note = "lembrou as palavras dele" },
		{ id = "blazerunner", name = "Blazerunner", note = "o inimigo que ele veio enfrentar" },
		{ id = "donova-snowden", name = "Donova Snowden", note = "temperou sua espada" },
		{ id = "eridan-bluewind", name = "Eridan Bluewind", note = "sabia o que ele buscava" },
	},
})

